use crate::aap::caps::state_rw;
use std::collections::BTreeSet;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let PublishedDigest {
            date,
            considered,
            published,
        } = published;

        let mut recorded: u32 = 0;

        // Only mark items seen once the digest that considered them has
        // actually been published. Otherwise the next run should consider
        // them again rather than silently dropping them.
        if published {
            let mut done: BTreeSet<&str> = BTreeSet::new();
            for id in considered.iter() {
                let id = id.as_str();
                if id.is_empty() || !done.insert(id) {
                    continue;
                }
                // Keep the first-seen date for items already recorded.
                if state_rw::get(id).is_some() {
                    continue;
                }
                state_rw::put(id, &date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport { date, recorded }
    }
}

export!(Node);
